export interface ParticleLimits {
  maxParticles: number;
  maxSpawnRate: number;
  maxParticleLifetime: number;
  maxEmitterLifetime: number;
}

export const PARTICLE_LIMITS: ParticleLimits = {
  maxParticles: 500,
  maxSpawnRate: 200,
  maxParticleLifetime: 30,
  maxEmitterLifetime: 120,
};

export function clampCount(value: number, max: number): number {
  if (!Number.isFinite(value) || value <= 0) return 0;
  return Math.min(Math.floor(value), max);
}
